# greedy clustering of strong neurons in token space
Xs=Xn[nr>np.percentile(nr,30)]
def kmeans(X,K,it=50,seed=0):
    rng=np.random.default_rng(seed); C=X[rng.choice(len(X),K,replace=False)]
    for _ in range(it):
        a=np.argmax(X@C.T,1)
        for k in range(K):
            m=X[a==k]
            if len(m): c=m.sum(0); C[k]=c/np.linalg.norm(c)
    return C,a,(X*C[a]).sum(1).mean()
for K in [10,20,27,35,45,60,80]:
    print(K, np.round(np.mean([kmeans(Xs,K,seed=s)[2] for s in range(3)]),3))
